#include <stddef.h>
#include <stdint.h>
static void put64(uint8_t*o,size_t p,int64_t x){uint64_t u=(uint64_t)x;for(size_t j=0;j<8;j++)o[p+j]=(uint8_t)(u>>(8*j));}
static int16_t narrow(int64_t x){return (int16_t)x;}
static void line(int16_t*d,size_t base,int k,int m,int n,const int16_t*r){int64_t t[12];for(int j=0;j<4;j++){t[j]=d[base+k*j]+d[base+k*(7-j)];t[7-j]=d[base+k*j]-d[base+k*(7-j)];}t[8]=t[0]+t[3];t[9]=t[0]-t[3];t[10]=t[1]+t[2];t[11]=t[1]-t[2];d[base]=narrow((t[8]+t[10])>>m);d[base+4*k]=narrow((t[8]-t[10])>>m);t[8]=(int16_t)(t[11]+t[9])*r[10];d[base+2*k]=narrow(t[8]+(int16_t)((t[9]*r[9])>>n));d[base+6*k]=narrow(t[8]+(int16_t)((t[11]*r[11])>>n));t[0]=(int16_t)(t[4]+t[7])*r[2];t[1]=(int16_t)(t[5]+t[6])*r[0];t[2]=t[4]+t[6];t[3]=t[5]+t[7];t[8]=(int16_t)(t[2]+t[3])*r[8];t[2]=(int16_t)t[2]*r[1]+t[8];t[3]=(int16_t)t[3]*r[3]+t[8];d[base+7*k]=narrow((int16_t)(t[4]*r[4]+t[0]+t[2])>>n);d[base+5*k]=narrow((int16_t)(t[5]*r[6]+t[1]+t[3])>>n);d[base+3*k]=narrow((int16_t)(t[6]*r[5]+t[1]+t[2])>>n);d[base+k]=narrow((int16_t)(t[7]*r[7]+t[0]+t[3])>>n);}
int64_t edn_jpeg_dct(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n!=76)return -1;int16_t d[64],r[12];for(size_t i=0;i<64;i++){if(v[i]<-8||v[i]>8)return -1;d[i]=(int16_t)v[i];}for(size_t i=0;i<12;i++){if(v[64+i]<-32||v[64+i]>31)return -1;r[i]=(int16_t)v[64+i];}if(!out||cap<512)return -2;for(size_t row=0;row<8;row++)line(d,row*8,1,0,13,r);for(size_t col=0;col<8;col++)line(d,col,8,3,16,r);for(size_t i=0;i<64;i++)put64(out,8*i,d[i]);return 512;}
